.table-pane { min-width: 0; padding: 22px; }.table-header { padding-bottom: 17px; border-bottom: 1px solid #e8edf4; }.table-header h3 { margin: 5px 0; color: #263f63; font-size: 20px; }.table-header p { margin: 0; color: #8a98aa; font-size: 12px; }.table-eyebrow { color: #5b87d3; }.header-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; }.table-filters { display: flex; align-items: center; gap: 12px; padding: 16px 0; }.table-filters :deep(.el-input) { width: 240px; }.table-filters :deep(.el-select) { width: 150px; }.table-count { margin-left: auto; color: #8190a5; font-size: 13px; }.store-table { width: 100%; overflow: hidden; border: 1px solid #e5eaf1; border-radius: 8px; }
.dialog-lead { margin: 0; color: #8290a5; font-size: 13px; line-height: 1.7; }.editor-form { display: grid; grid-template-columns: 1fr 1fr 120px; gap: 14px; padding: 20px 0 4px; }.editor-form-stacked { grid-template-columns: 1fr; gap: 17px; padding-top: 24px; }.editor-form label, .group-editor-field { display: flex; flex-direction: column; gap: 7px; color: #5d6e87; font-size: 13px; font-weight: 650; }.editor-form-stacked label:last-child { width: 170px; }.dialog-spacer { display: inline-block; width: 120px; }.group-editor-field { margin-top: 23px; }.group-editor-select { width: 100%; }
