@media (max-width: 720px) { .region-hero { align-items: flex-start; flex-direction: column; }.region-console { grid-template-columns: 1fr; }.tree-pane { max-height: 300px; border-right: 0; border-bottom: 1px solid #e5eaf1; }.table-pane { padding: 16px; }.table-header, .table-filters { align-items: flex-start; flex-direction: column; }.table-filters :deep(.el-input), .table-filters :deep(.el-select) { width: 100%; }.table-count { margin-left: 0; }.editor-form { grid-template-columns: 1fr; }.editor-form label:last-child { grid-column: auto; } }
